import { LiquidProduct, Product } from "@sections/product";

class ProductSwatches extends HTMLElement {
  private _productData: LiquidProduct | null = null;

  private _productComponent: Product | null = null;

  private _variantInputElement: HTMLInputElement | null = null;

  constructor() {
    super();
  }

  static get observedAttributes() {
    return ["product"];
  }

  connectedCallback() {
    this._productComponent = document.querySelector("uwp-product");
    this._variantInputElement = this.querySelector("[data-variant-input]");
    if (!this._productComponent || !this._variantInputElement) return;
    this.parseProductData();
    this.setupEventListeners();
  }

  attributeChangedCallback(name: string, oldValue: string, newValue: string) {
    if (name === "product" && newValue !== oldValue) {
      this.parseProductData();
    }
  }

  private parseProductData() {
    const product = this.getAttribute("product");
    if (product) {
      this._productData = JSON.parse(product) as LiquidProduct;
    }
  }

  private setupEventListeners() {
    const inputs = this.querySelectorAll('input[type="radio"]');
    inputs.forEach((input) => {
      input.addEventListener("change", this.onOptionChange.bind(this));
    });
  }

  private onOptionChange(event: Event) {
    const input = event.target as HTMLInputElement;
    this.updateSelectedOptions();
    const label = input
      .closest("fieldset")
      ?.querySelector("[data-selected-swatch-value") as HTMLElement;
    if (!label) return;
    label.textContent = input.value;
  }

  private updateSelectedOptions() {
    if (!this._productData) return;
    const productComponent = this._productComponent;
    if (!productComponent) return;
    const selectedInputs = Array.from(
      this.querySelectorAll('input[type="radio"]:checked'),
    );
    const selectedOptions = selectedInputs.map((input) => ({
      name: (input as HTMLInputElement).name,
      value: (input as HTMLInputElement).value,
    }));

    if (
      selectedOptions.length !== this._productData.variants[0].options.length
    ) {
      return;
    }
    const matchingVariant = this._productData.variants.find((variant) =>
      selectedOptions.every((selectedOption) =>
        variant.options.some((option) => option.includes(selectedOption.value)),
      ),
    );

    if (!matchingVariant) {
      return;
    }
    productComponent.setSelectedVariantId(matchingVariant.id);
    this._variantInputElement?.setAttribute("value", matchingVariant.id);
  }
}

customElements.define("uwp-product-swatches", ProductSwatches);
